const test = require("node:test");
const assert = require("node:assert/strict");
const { verifyTotpCode } = require("../services/totp");

test("existing base32 enrollment and v12 TOTP code remain valid after the v13 migration", async (context) => {
  let now = Date.UTC(2024, 0, 1);
  context.mock.method(Date, "now", () => now);
  // Fixed code generated by otplib v12 for this previously enrolled secret.
  const secret = "JBSWY3DPEHPK3PXPJBSWY3DPEHPK3PXP";
  assert.equal(await verifyTotpCode(secret, "277525"), true);
  assert.equal(await verifyTotpCode(secret, "277526"), false);
  now += 30_000;
  assert.equal(await verifyTotpCode(secret, "277525"), true);
  now += 30_000;
  assert.equal(await verifyTotpCode(secret, "277525"), false);
});

test("malformed TOTP input is denied without throwing", async () => {
  const secret = "JBSWY3DPEHPK3PXPJBSWY3DPEHPK3PXP";
  for (const code of [null, undefined, {}, [], "bad", "12345", "1234567", "123 456"]) {
    assert.equal(await verifyTotpCode(secret, code), false);
  }
  assert.equal(await verifyTotpCode("", "277525"), false);
});
